  function rebuild(){const old=model&&model.times.length>1?S.step/(model.times.length-1):0;model=buildModel(S);S.step=Math.round(old*(model.times.length-1));S.inspect=Math.min(S.inspect,model.conds.length-1);if(stepCtl){stepCtl.el.max=model.times.length-1;stepCtl.set(S.step);}if(inspectCtl){inspectCtl.el.max=model.conds.length-1;inspectCtl.set(S.inspect);}drawFrame();}
