  let f=ctlGroup('Scanner-informed condition set');slider(f,'main field B0',.05,.10,.005,S.B0T,v=>(v*1e3).toFixed(0)+' mT',v=>{S.B0T=v;rebuild();});slider(f,'mean off-resonance',-100,100,2,S.fieldMean,v=>(v>0?'+':'')+v+' Hz',v=>{S.fieldMean=v;rebuild();});slider(f,'intravoxel B0 span',0,100,2,S.fieldSpan,v=>'±'+v+' Hz',v=>{S.fieldSpan=v;rebuild();});slider(f,'field direction: z ↔ transverse',0,90,5,S.fieldAngle,v=>v+'°',v=>{S.fieldAngle=v;rebuild();});slider(f,'B1 variation',0,.25,.01,S.b1Spread,v=>'±'+(100*v).toFixed(0)+'%',v=>{S.b1Spread=v;rebuild();});slider(f,'calibration bins',3,7,2,S.nBins,v=>v,v=>{S.nBins=Math.round(v)|1;S.inspect=0;rebuild();});
