  const seq=mkCanvas(stage,1180,190,'A · finite slice-selective echo-train sequence and receiver times');seq.parentElement.classList.add('echo-train-wide','echo-train-sequence');const read=document.createElement('div');read.className='echo-train-readout';stage.appendChild(read);
  explain(`<b>Figure 27.</b> Each scanner condition keeps its own complex RF taps and amplitudes while sharing a conservative union topology. A detected contribution is labelled <span style="color:${ECHO_COL.ge}">GE</span> if gradient encoding is later rewound without RF conjugation, <span style="color:${ECHO_COL.se}">SE</span> after transverse F<sup>+</sup>↔F<sup>−</sup> conjugation, and <span style="color:${ECHO_COL.ste}">STE</span> only after transverse magnetization was stored in Z and recalled. These complex components are combined only at signal formation.`);
  const row=document.createElement('div');row.className='echo-train-grid';stage.appendChild(row);const paths=mkCanvas(row,760,500,'B · signed-kz phase diagram with ancestry-classified receiver crossings');paths.parentElement.classList.add('echo-train-paths');const cond=mkCanvas(row,520,500,'C · low-field condition phase and contribution matrix');const signal=mkCanvas(stage,1180,410,'D · coherent echo train and pathway-class decomposition');signal.parentElement.classList.add('echo-train-wide','echo-train-signal');const metrics=A.addMetricRow(stage,[]);let model=null,selCtl,inspectCtl,refCtl,offsetCtl,optStatus='No search run.';
